INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20PQF10', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $5x - 15 = 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The correct answer is $3$. To solve $5x - 15 = 0$, add $15$ to both sides to get $5x = 15$, then divide both sides by $5$ to get $x = 3$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20S6FH7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 30 students, 18 play soccer, 12 play basketball, and 6 play both soccer and basketball. If a student is selected at random from those who play soccer, what is the probability that the student also plays basketball?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{1}{5}\\)"},{"key":"B","text":"\\(\\dfrac{1}{3}\\)"},{"key":"C","text":"\\(\\dfrac{2}{5}\\)"},{"key":"D","text":"\\(\\dfrac{1}{2}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question: P(basketball | soccer) = (number who play both) / (number who play soccer) = \\(\\dfrac{6}{18} = \\dfrac{1}{3}\\). Option A (\\(\\dfrac{1}{5}\\)) divides 6 by 30 (the entire class), computing P(both) rather than the conditional probability. Option C (\\(\\dfrac{2}{5}\\)) divides 12 by 30, computing P(basketball) unconditionally. Option D (\\(\\dfrac{1}{2}\\)) divides 6 by 12, conditioning on basketball players instead of soccer players.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM213ZIMH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A shirt originally costs $40. It is on sale for 15% off. What is the sale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '34', ARRAY['34'], E'The discount is \\(40 \\times 0.15 = 6\\) dollars. The sale price is \\(40 - 6 = 34\\) dollars. Equivalently, \\(40 \\times 0.85 = 34\\).', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM218UOOW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $x^2 + 4x + 5 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = 16 - 20 = -4$. Since the discriminant is negative, the equation has no real solutions. The answer is A. Option B ($1$) reflects a concept gap: confusing a negative discriminant with a zero discriminant, which would give exactly one repeated root. Option C ($2$) results from misreading the question: assuming all quadratics have two real solutions without checking the discriminant. Option D ($4$) is partial reasoning: using the coefficient $b = 4$ as the number of solutions rather than computing the discriminant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM219BSLG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has its center at $(3, -2)$ and passes through the point $(7, 1)$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The correct answer is $5$. The radius equals the distance from the center $(3, -2)$ to the point $(7, 1)$ on the circle. Using the distance formula: $r = \\sqrt{(7 - 3)^2 + (1 - (-2))^2} = \\sqrt{4^2 + 3^2} = \\sqrt{16 + 9} = \\sqrt{25} = 5$. A common error is to forget to handle the negative sign in $-2$, computing $\\sqrt{16 + 1} = \\sqrt{17}$. Another error is to add the coordinates instead of subtracting, or to forget to square the differences.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22D0MS4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 3 red marbles, 5 blue marbles, and 2 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{1}{5}\\)"},{"key":"B","text":"\\(\\dfrac{3}{10}\\)"},{"key":"C","text":"\\(\\dfrac{1}{2}\\)"},{"key":"D","text":"\\(\\dfrac{3}{5}\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of marbles is \\(3 + 5 + 2 = 10\\). The number of blue marbles is 5, so the probability of selecting a blue marble is \\(\\dfrac{5}{10} = \\dfrac{1}{2}\\). Option A (\\(\\dfrac{1}{5}\\)) results from dividing 2 by 10 or an arithmetic error in simplification. Option B (\\(\\dfrac{3}{10}\\)) uses the count of red marbles instead of blue. Option D (\\(\\dfrac{3}{5}\\)) incorrectly counts 6 blue marbles or misreads the problem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22MQ5AF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $x \\neq -\\frac{1}{2}$, which expression is equivalent to $\\frac{2x^2 + 7x + 3}{2x + 1}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 3$"},{"key":"B","text":"$x + 3$"},{"key":"C","text":"$x + 7$"},{"key":"D","text":"$2x - 3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator: $2x^2 + 7x + 3 = (2x + 1)(x + 3)$. Verify: $(2x + 1)(x + 3) = 2x^2 + 6x + x + 3 = 2x^2 + 7x + 3$. Cancelling $(2x + 1)$ gives $x + 3$, so the answer is B. Option A ($2x + 3$) reflects a concept gap: keeping the leading coefficient $2$ after cancellation, as if the quotient must match the degree-1 coefficient of the numerator. Option C ($x + 7$) is partial reasoning: incorrectly using the middle coefficient $7$ as the constant term. Option D ($2x - 3$) is a sign error: flipping the sign of the constant during factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM233RXVW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular box has a length of $5$ inches, a width of $3$ inches, and a height of $4$ inches. What is the volume, in cubic inches, of the box?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'The correct answer is $60$. The volume of a rectangular box is $V = l \\times w \\times h = 5 \\times 3 \\times 4 = 60$ cubic inches. A common error is to compute the surface area ($2(5 \\cdot 3 + 5 \\cdot 4 + 3 \\cdot 4) = 2(15 + 20 + 12) = 94$) instead of the volume. Another error is to add the dimensions ($5 + 3 + 4 = 12$) rather than multiply them.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23SNUO5', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'For $x \\neq -3$, which expression is equivalent to $\\frac{x^2 - 9}{x + 3}$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 3$"},{"key":"B","text":"$x - 3$"},{"key":"C","text":"$x^2 - 3$"},{"key":"D","text":"$-x + 3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor the numerator as a difference of squares: $x^2 - 9 = (x - 3)(x + 3)$. Cancelling the common factor $(x + 3)$ gives $x - 3$, so the answer is B. Option A ($x + 3$) is a sign error: incorrectly factoring as $(x + 3)(x + 3)$ instead of $(x - 3)(x + 3)$. Option C ($x^2 - 3$) reflects a concept gap: attempting to cancel the $3$ from $9$ with the $3$ in the denominator without factoring. Option D ($-x + 3$) is an arithmetic slip from negating the result after cancellation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24R7FOJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $ABC$ with the right angle at $C$, $\\sin A = \\frac{5}{13}$. What is the value of $\\cos A$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{12}$"},{"key":"B","text":"$\\frac{8}{13}$"},{"key":"C","text":"$\\frac{12}{13}$"},{"key":"D","text":"$\\frac{13}{12}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. Since $\\sin A = \\frac{5}{13}$, the side opposite angle $A$ is $5$ and the hypotenuse is $13$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{13^2 - 5^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. Therefore $\\cos A = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{12}{13}$. Option A ($\\frac{5}{12}$) gives $\\tan A$ instead of $\\cos A$, confusing the trigonometric ratios. Option B ($\\frac{8}{13}$) results from computing $13 - 5 = 8$ and using $\\frac{8}{13}$, an arithmetic shortcut instead of the Pythagorean theorem. Option D ($\\frac{13}{12}$) inverts the cosine ratio, giving $\\sec A$ instead of $\\cos A$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24TIXLQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(1, 4)$ and $(3, 10)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. First, find the slope: $m = \\frac{10 - 4}{3 - 1} = \\frac{6}{2} = 3$. Using point-slope form with $(1, 4)$: $y - 4 = 3(x - 1)$, which gives $y = 3x + 1$. The $y$-intercept is $1$. Option A ($-2$) results from a sign error when solving for the intercept. Option C ($3$) is the slope, not the $y$-intercept, reflecting incomplete reasoning. Option D ($7$) comes from an arithmetic error such as adding the slope to the $y$-coordinate of the first point.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24V46KT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A standard deck of 52 playing cards contains 4 suits of 13 cards each. Two cards are drawn at random without replacement. Given that the first card drawn is a heart, what is the probability that the second card drawn is also a heart?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{13}{52}\\)"},{"key":"B","text":"\\(\\dfrac{12}{52}\\)"},{"key":"C","text":"\\(\\dfrac{12}{51}\\)"},{"key":"D","text":"\\(\\dfrac{13}{51}\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'After one heart is drawn, 12 hearts remain out of 51 total cards, so the conditional probability is \\(\\dfrac{12}{51}\\). Option A (\\(\\dfrac{13}{52}\\)) ignores that a heart was already removed, treating the draws as independent. Option B (\\(\\dfrac{12}{52}\\)) correctly reduces the hearts to 12 but fails to reduce the total from 52 to 51. Option D (\\(\\dfrac{13}{51}\\)) reduces the total deck but does not remove the drawn heart from the heart count.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25CQJX2', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The equation $ax + by = 24$ represents a line that passes through the point $(3, 6)$ and has a slope of $-2$. What is the value of $a + b$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. For the equation $ax + by = 24$, the slope is $-\\frac{a}{b}$. Setting this equal to $-2$ gives $\\frac{a}{b} = 2$, so $a = 2b$. Substituting the point $(3, 6)$ into the equation: $3a + 6b = 24$. Replacing $a$ with $2b$: $3(2b) + 6b = 24$, so $6b + 6b = 24$, giving $12b = 24$ and $b = 2$. Then $a = 2(2) = 4$, and $a + b = 4 + 2 = 6$. Option A ($4$) comes from finding only the value of $a$ without adding $b$. Option C ($8$) results from incorrectly setting up the slope relationship as $a = b$ instead of $a = 2b$. Option D ($12$) comes from an arithmetic error in solving the system.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25EGS0L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'Lines $p$ and $q$ are parallel, and line $t$ is a transversal that intersects them. The alternate interior angles formed have measures $(3x + 5)^\\circ$ and $(5x - 25)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$15$"},{"key":"C","text":"$17.5$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. Alternate interior angles formed by parallel lines and a transversal are equal, so $3x + 5 = 5x - 25$. Subtracting $3x$ from both sides gives $5 = 2x - 25$. Adding $25$ to both sides gives $30 = 2x$, so $x = 15$. To verify: $3(15) + 5 = 50^\\circ$ and $5(15) - 25 = 50^\\circ$. Option A ($10$) results from a sign error when rearranging, such as obtaining $-2x = -20$ instead of the correct $-2x = -30$. Option C ($17.5$) comes from an arithmetic slip, such as dividing $35$ by $2$ instead of $30$ by $2$. Option D ($25$) results from treating the angles as co-interior (same-side interior) angles summing to $180^\\circ$: $3x + 5 + 5x - 25 = 180$ gives $8x - 20 = 180$, so $8x = 200$ and $x = 25$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26BO77U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'In a school of 600 students, 45% are enrolled in a science course and 30% are enrolled in an art course. If 10% of all students are enrolled in both courses, how many students are enrolled in at least one of the two courses?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '390', ARRAY['390'], E'Using the inclusion-exclusion principle: students in science = \\(600 \\times 0.45 = 270\\), students in art = \\(600 \\times 0.30 = 180\\), students in both = \\(600 \\times 0.10 = 60\\). Students in at least one course = \\(270 + 180 - 60 = 390\\).', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26JBI5M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A company randomly assigns 500 employees to either a standing-desk group or a traditional-desk group and measures productivity after 3 months. The standing-desk group shows a 12% increase in productivity. Which conclusion is most appropriate?', NULL, $lyceon_json$[{"key":"A","text":"Standing desks are associated with higher productivity, but a causal relationship cannot be established."},{"key":"B","text":"Standing desks cause a 12% increase in productivity for all workers."},{"key":"C","text":"There is evidence that standing desks cause increased productivity among the employees in this study."},{"key":"D","text":"The results are invalid because the employees knew which group they were in."}]$lyceon_json$::jsonb, 'C', NULL, E'Because participants were randomly assigned to treatment groups, this is a randomized experiment, which does support a causal conclusion for the study population. Option A incorrectly applies the limitation of observational studies; random assignment allows causal inference. Option B overgeneralizes to all workers, whereas the conclusion applies to the employees in this company. Option D is incorrect because awareness of group assignment does not automatically invalidate results in a randomized experiment; while blinding strengthens an experiment, the random assignment still supports causal inference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26RHLCJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A printing company charges a flat setup fee of $\\$50$ plus $\\$0.15$ per page. A second company charges no setup fee but $\\$0.40$ per page. For what number of pages will the total charges from both companies be equal?', NULL, $lyceon_json$[{"key":"A","text":"$125$"},{"key":"B","text":"$200$"},{"key":"C","text":"$250$"},{"key":"D","text":"$500$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. Let $p$ represent the number of pages. The first company''s charge is $50 + 0.15p$ and the second company''s charge is $0.40p$. Setting them equal: $50 + 0.15p = 0.40p$. Subtracting $0.15p$ from both sides gives $50 = 0.25p$. Dividing both sides by $0.25$ yields $p = 200$. Option A ($125$) results from dividing the setup fee by only the second company''s per-page rate ($50 \\div 0.40 = 125$) rather than by the difference in rates. Option C ($250$) comes from using an incorrect rate difference of $0.20$ instead of $0.25$. Option D ($500$) results from an arithmetic error in computing $50 \\div 0.25$ incorrectly as $50 \\div 0.10$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM279O5PC', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What is the solution to the inequality $2x - 5 \\geq 9$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 7$"},{"key":"B","text":"$x \\leq 7$"},{"key":"C","text":"$x \\geq 2$"},{"key":"D","text":"$x \\geq 14$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is A. To solve $2x - 5 \\geq 9$, add $5$ to both sides to get $2x \\geq 14$, then divide both sides by $2$ to get $x \\geq 7$. Option B reverses the direction of the inequality sign. Option C results from incorrectly computing $9 - 5 = 4$ and then $\\frac{4}{2} = 2$, applying the wrong operation. Option D stops after adding $5$ to both sides without dividing by $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27XPSWT', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(x + 4) - 2(x - 1)$?', NULL, $lyceon_json$[{"key":"A","text":"$x + 14$"},{"key":"B","text":"$x + 10$"},{"key":"C","text":"$5x + 14$"},{"key":"D","text":"$5x + 10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3x + 12 - 2x + 2 = x + 14$, so the answer is A. Option B ($x + 10$) results from a sign error: treating $-2(-1)$ as $-2$ instead of $+2$, yielding $12 - 2 = 10$. Option C ($5x + 14$) results from an arithmetic slip: adding the coefficients $3 + 2 = 5$ instead of subtracting $3 - 2 = 1$. Option D ($5x + 10$) combines both errors: adding the $x$-coefficients and making the sign error on the constant.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A0UM9Y', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function is defined by $f(x) = 2x + 5$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$8$"},{"key":"C","text":"$11$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. Substitute $x = 3$ into $f(x) = 2x + 5$: $f(3) = 2(3) + 5 = 6 + 5 = 11$. Option A ($6$) results from computing only $2(3)$ without adding $5$. Option B ($8$) comes from incorrectly computing $3 + 5$ instead of $2(3) + 5$. Option D ($16$) results from computing $2(3 + 5) = 2(8) = 16$, applying the multiplication to the entire sum rather than just $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ASW6U0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$\\begin{cases} 3x + 2y = 16 \\\\ x - y = 2 \\end{cases}$$ What is the value of $x + y$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$6$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. From the second equation, $x = y + 2$. Substituting into the first equation: $3(y + 2) + 2y = 16$, which simplifies to $3y + 6 + 2y = 16$, then $5y = 10$, so $y = 2$. Substituting back gives $x = 2 + 2 = 4$. Therefore $x + y = 4 + 2 = 6$. Option A ($2$) is just the value of $y$, stopping before computing the requested expression. Option B ($4$) is just the value of $x$, not $x + y$. Option D ($8$) results from an arithmetic error, such as computing $5y = 20$ instead of $5y = 10$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CVN9E2', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A store charges a flat fee of $\\$8$ for shipping plus $\\$3$ per item ordered. A customer has at most $\\$35$ to spend on shipping. What is the greatest number of items the customer can order?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$10$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. Let $n$ represent the number of items. The total shipping cost is $8 + 3n$, which must be at most $\\$35$: $8 + 3n \\leq 35$. Subtracting $8$ from both sides gives $3n \\leq 27$. Dividing both sides by $3$ gives $n \\leq 9$. The greatest whole number satisfying this is $9$. Option A ($7$) results from an arithmetic error such as computing $35 - 8 = 21$ instead of $27$. Option C ($10$) reflects a misunderstanding of the $\\leq$ boundary, treating $n < 10$ as allowing $n = 10$. Option D ($11$) results from omitting the flat fee and computing $\\lfloor 35 \\div 3 \\rfloor = 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DF2GJQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A health researcher surveys 1,000 adults selected at random from a city and finds that those who exercise regularly report lower stress levels than those who do not. The researcher concludes that exercise reduces stress. Which of the following is a valid criticism of this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 1,000 is too small to draw any conclusion."},{"key":"B","text":"Because participants were not randomly assigned to exercise or not exercise, confounding variables may explain the difference."},{"key":"C","text":"The random selection of participants ensures that a causal conclusion is valid."},{"key":"D","text":"The study should have used a smaller sample to reduce variability in the results."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study because participants self-selected into exercise or no-exercise groups; no treatment was assigned. Without random assignment, confounding variables (such as income, free time, or general health) could explain the observed association, so a causal conclusion is not warranted. Option A is incorrect because 1,000 is a reasonably large sample for drawing statistical conclusions. Option C confuses random selection (which supports generalizability to the population) with random assignment (which supports causal inference); random selection alone does not justify a causal claim. Option D is incorrect because reducing sample size increases variability and weakens conclusions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DHC25B', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'Which of the following inequalities has no solution?', NULL, $lyceon_json$[{"key":"A","text":"$3(x - 2) > 3x - 7$"},{"key":"B","text":"$2(x + 1) \\leq 2x + 2$"},{"key":"C","text":"$5x - 3 > 5(x + 1)$"},{"key":"D","text":"$4x + 1 \\geq 2(2x - 3)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. Distributing on the right side gives $5x - 3 > 5x + 5$. Subtracting $5x$ from both sides yields $-3 > 5$, which is false for all values of $x$, so there is no solution. Option A simplifies to $3x - 6 > 3x - 7$, which reduces to $-6 > -7$; this is always true, meaning all real numbers are solutions. A student who selects A may have made a sign error evaluating $-6 > -7$. Option B simplifies to $2x + 2 \\leq 2x + 2$, which reduces to $0 \\leq 0$; this is always true. A student who selects B may confuse an identity (all solutions) with no solution. Option D simplifies to $4x + 1 \\geq 4x - 6$, which reduces to $1 \\geq -6$; this is always true. A student who selects D may have incorrectly distributed $2(2x - 3)$ as $4x + 6$ and then obtained a false statement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EHC4DH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A class of 20 students takes a quiz. The mean score is 78 and the median score is 82. A new student joins the class and scores 90 on the quiz. Which of the following must be true about the updated class of 21 students?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases and the median increases."},{"key":"B","text":"The mean increases and the median stays the same."},{"key":"C","text":"The mean increases and the median does not decrease."},{"key":"D","text":"The mean stays the same and the median increases."}]$lyceon_json$::jsonb, 'C', NULL, E'The original sum of scores is \\(20 \\times 78 = 1{,}560\\). With the new score, the sum is \\(1{,}560 + 90 = 1{,}650\\), and the new mean is \\(\\frac{1{,}650}{21} \\approx 78.57\\), which is greater than 78, so the mean increases. For the median: with 20 students the median is the average of the 10th and 11th values, equal to 82. With 21 students, the median is the 11th value. Since 90 is inserted above the median, the 11th value is at least as large as the original 11th value, which was at least 82 (because the average of the 10th and 11th was 82 and the 11th is at least the 10th). So the new median is at least 82 — it does not decrease. However, the median might stay at 82 or increase depending on the specific values, so we cannot guarantee it strictly increases. A is wrong because the median might not increase (concept gap). B is wrong because the median might increase rather than stay the same (partial reasoning). D is wrong because the mean definitely increases, not stays the same (arithmetic_slip in computing the new mean).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FGG36S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'Researchers found that students who eat breakfast daily have higher test scores than students who skip breakfast. The study recorded students'' existing habits without any intervention. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"A controlled experiment"},{"key":"B","text":"An observational study"},{"key":"C","text":"A census"},{"key":"D","text":"A sample survey"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researchers observed students'' existing habits without assigning treatments or interventions, this is an observational study. Option A is incorrect because a controlled experiment requires the researchers to assign subjects to treatment and control groups. Option C is incorrect because a census collects data from every member of a population, which is not described here. Option D is incorrect because a sample survey collects self-reported data via questionnaire, whereas this study recorded habits and test scores as observed data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G1FLAD', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g(x) = -3x + 12$ models the number of gallons of water remaining in a tank after $x$ hours of draining. After how many hours will the tank be empty?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$3$"},{"key":"C","text":"$4$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. The tank is empty when $g(x) = 0$. Setting $-3x + 12 = 0$ gives $-3x = -12$, so $x = 4$. The tank is empty after $4$ hours. Option A ($-4$) results from a sign error when dividing $-12$ by $-3$. Option B ($3$) comes from using the absolute value of the rate of change rather than solving the equation. Option D ($12$) results from reporting the initial amount of water (the $y$-intercept) instead of solving for when the water reaches zero.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GNNH5O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right circular cone has a volume of $48\\pi$ cubic inches and a height of $9$ inches. What is the radius, in inches, of the base of the cone?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'The correct answer is $4$. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h$. Substituting the given values: $48\\pi = \\frac{1}{3}\\pi r^2(9)$. Simplifying the right side: $48\\pi = 3\\pi r^2$. Dividing both sides by $3\\pi$: $r^2 = 16$, so $r = 4$. A common error is to omit the $\\frac{1}{3}$ factor and use the cylinder formula $V = \\pi r^2 h$, which gives $48\\pi = 9\\pi r^2$, so $r^2 = \\frac{48}{9} = \\frac{16}{3}$ and $r = \\frac{4}{\\sqrt{3}}$. Another error is to solve correctly for $r^2 = 16$ but report $r^2 = 16$ as the answer instead of $r = 4$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IS5VJA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A map uses a scale of 1 inch to 12 miles. Two cities are 4.5 inches apart on the map. A car travels between the two cities at an average speed of 40 miles per hour. How many minutes does the trip take?', NULL, $lyceon_json$[{"key":"A","text":"54"},{"key":"B","text":"75"},{"key":"C","text":"81"},{"key":"D","text":"95"}]$lyceon_json$::jsonb, 'C', NULL, E'The distance between the cities is \\(4.5 \\times 12 = 54\\) miles. The travel time is \\(\\frac{54}{40} = 1.35\\) hours. Converting to minutes: \\(1.35 \\times 60 = 81\\) minutes. A is wrong because it gives the distance in miles rather than the time in minutes (partial reasoning). B is wrong due to an arithmetic slip in computing the distance (using 50 instead of 54 miles, giving 50 ÷ 40 = 1.25 hours = 75 minutes). D is wrong because it misapplies the unit conversion from hours to minutes: treating 1.35 hours as 1 hour and 35 minutes to get 95, rather than correctly computing 1.35 × 60 = 81.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JULEM0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemist mixes chemical A and chemical B in a ratio of 3:5 by volume to prepare a solution. She uses all 12 liters of chemical A she has available. After mixing, she adds water to the resulting mixture to increase its total volume by 25%. What is the total volume, in liters, of the final mixture?', NULL, $lyceon_json$[{"key":"A","text":"32"},{"key":"B","text":"35"},{"key":"C","text":"40"},{"key":"D","text":"48"}]$lyceon_json$::jsonb, 'C', NULL, E'Since chemicals A and B are in the ratio 3:5 and chemical A is 12 liters, chemical B is \\(12 \\times \\frac{5}{3} = 20\\) liters. The mixture before adding water is \\(12 + 20 = 32\\) liters. Increasing the volume by 25%: \\(32 \\times 1.25 = 40\\) liters. A is wrong because it stops at the mixture volume before adding water (partial reasoning). B is wrong because it applies the 25% increase only to chemical A (\\(12 \\times 1.25 = 15\\), then \\(15 + 20 = 35\\)), a concept gap about what quantity the percentage applies to. D is wrong because it applies a 50% increase instead of 25% (\\(32 \\times 1.5 = 48\\)), an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L56VR3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, the measure of angle $D$ is twice the measure of angle $E$, and the measure of angle $F$ is $60^\\circ$. What is the measure, in degrees, of angle $D$?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$60$"},{"key":"C","text":"$80$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. Let the measure of angle $E$ be $x$. Then angle $D = 2x$ and angle $F = 60^\\circ$. Since the angles of a triangle sum to $180^\\circ$: $2x + x + 60 = 180$, so $3x = 120$ and $x = 40$. Therefore angle $D = 2(40) = 80^\\circ$. Option A ($40^\\circ$) is the measure of angle $E$, not angle $D$ — a partial-reasoning error of solving for $x$ but not computing $2x$. Option B ($60^\\circ$) simply repeats the given measure of angle $F$. Option D ($120^\\circ$) results from computing $180 - 60 = 120$ without distributing that remainder between angles $D$ and $E$ according to their ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M0SY2W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours of sunlight per day (\\(x\\)) and the height of a plant in centimeters (\\(y\\)) over several weeks. The line of best fit is \\(y = 1.5x + 4\\). A data point at \\(x = 10\\) has an actual \\(y\\)-value of 22. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"\\(-3\\)"},{"key":"B","text":"3"},{"key":"C","text":"19"},{"key":"D","text":"22"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value at \\(x = 10\\) is \\(y = 1.5(10) + 4 = 19\\). The residual is actual minus predicted: \\(22 - 19 = 3\\). A is wrong because it computes predicted minus actual (\\(19 - 22 = -3\\)), a sign error in the residual formula. C is wrong because it reports the predicted value rather than the residual (partial reasoning). D is wrong because it reports the actual value rather than the residual (misread question).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OGSSVL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'The line of best fit for a scatterplot is given by the equation \\(y = 2x + 3\\). What is the predicted value of \\(y\\) when \\(x = 7\\)?', NULL, $lyceon_json$[{"key":"A","text":"10"},{"key":"B","text":"14"},{"key":"C","text":"17"},{"key":"D","text":"20"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting \\(x = 7\\) into the equation: \\(y = 2(7) + 3 = 14 + 3 = 17\\). A is wrong because it computes \\(7 + 3 = 10\\), ignoring the coefficient of 2 (partial reasoning). B is wrong because it computes \\(2 \\times 7 = 14\\) but omits the constant term +3 (partial reasoning). D is wrong because it computes \\(2(7 + 3) = 20\\), adding before multiplying — an equation setup error in applying order of operations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PM4UOF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 5x + 6 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 1$ and $x = 6$"},{"key":"B","text":"$x = -2$ and $x = -3$"},{"key":"C","text":"$x = 2$ and $x = 3$"},{"key":"D","text":"$x = -1$ and $x = -6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factor: $x^2 - 5x + 6 = (x - 2)(x - 3) = 0$, giving $x = 2$ or $x = 3$. Check: $2 + 3 = 5$ and $2 \\times 3 = 6$. The answer is C. Option A ($x = 1, x = 6$) reflects a concept gap: choosing factors of $6$ that multiply to $6$ but do not sum to $5$. Option B ($x = -2, x = -3$) is a sign error: using the factors but applying wrong signs (these would produce $x^2 + 5x + 6$). Option D ($x = -1, x = -6$) is an equation setup error: picking factor pairs of $6$ with incorrect signs and sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QJU1L9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'Data collected from 50 cities show a positive linear association between population density (in people per square mile) and average commute time (in minutes). The correlation coefficient is \\(r = 0.78\\). Which of the following conclusions is justified?', NULL, $lyceon_json$[{"key":"A","text":"Increasing population density causes longer commute times."},{"key":"B","text":"Approximately 78% of the variation in average commute time is explained by population density."},{"key":"C","text":"Approximately 61% of the variation in average commute time is explained by population density."},{"key":"D","text":"For every additional person per square mile, the average commute time increases by 0.78 minutes."}]$lyceon_json$::jsonb, 'C', NULL, E'The coefficient of determination is \\(r^2 = 0.78^2 \\approx 0.6084\\), so approximately 61% of the variation in average commute time is explained by population density. A is wrong because correlation does not imply causation — the study is observational, not experimental (concept gap). B is wrong because it confuses \\(r\\) with \\(r^2\\): the correlation coefficient \\(r = 0.78\\) does not mean 78% of the variation is explained (concept gap about the distinction between \\(r\\) and \\(r^2\\)). D is wrong because the correlation coefficient is not the slope of the regression line — \\(r\\) measures the strength and direction of linear association, not the rate of change (concept gap about interpreting \\(r\\)).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QUFCWI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has 8 values: 12, 15, 15, 18, 20, 22, 25, 33. What is the interquartile range (IQR) of this data set?', NULL, $lyceon_json$[{"key":"A","text":"7"},{"key":"B","text":"8.5"},{"key":"C","text":"10"},{"key":"D","text":"21"}]$lyceon_json$::jsonb, 'B', NULL, E'The lower half of the data is {12, 15, 15, 18}, so \\(Q_1 = \\frac{15 + 15}{2} = 15\\). The upper half is {20, 22, 25, 33}, so \\(Q_3 = \\frac{22 + 25}{2} = 23.5\\). The IQR is \\(Q_3 - Q_1 = 23.5 - 15 = 8.5\\). A is wrong due to an arithmetic slip (computing 22 − 15 = 7, using a single quartile boundary value instead of the median of each half). C is wrong because it computes 25 − 15 = 10, an equation setup error using raw data values rather than the quartile medians. D is wrong because it gives the range (33 − 12 = 21), confusing range with interquartile range (concept gap).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RCC4EC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $h(x) = -2(x - 1)^2 + 8$ models the height, in feet, of a ball $x$ seconds after being thrown. For how many seconds is the ball at or above a height of $6$ feet?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$2$"},{"key":"C","text":"$3$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set $h(x) \\geq 6$: $-2(x - 1)^2 + 8 \\geq 6$, so $-2(x - 1)^2 \\geq -2$, giving $(x - 1)^2 \\leq 1$. This means $-1 \\leq x - 1 \\leq 1$, so $0 \\leq x \\leq 2$. The ball is at or above $6$ feet for $2 - 0 = 2$ seconds. The answer is B. Option A ($1$) is partial reasoning: finding only one boundary point (e.g., $x = 1$) or computing half the interval length. Option C ($3$) reflects a concept gap: counting the integer time values $\\{0, 1, 2\\}$ as three instead of measuring the continuous interval length of $2$. Option D ($4$) results from a sign error: failing to flip the inequality when dividing by $-2$, yielding $(x - 1)^2 \\geq 1$ and then incorrectly computing the interval as $x \\leq 0$ or $x \\geq 2$, misinterpreting the total duration as $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RCEYKY', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The line $4x - 3y = 12$ is perpendicular to a line that passes through the point $(6, -1)$. What is the $y$-intercept of the perpendicular line?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$-\\frac{7}{2}$"},{"key":"C","text":"$\\frac{3}{4}$"},{"key":"D","text":"$\\frac{7}{2}$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is D. Rewrite $4x - 3y = 12$ in slope-intercept form: $y = \\frac{4}{3}x - 4$, so the slope is $\\frac{4}{3}$. The perpendicular slope is the negative reciprocal: $-\\frac{3}{4}$. Using point-slope form with $(6, -1)$: $y - (-1) = -\\frac{3}{4}(x - 6)$, giving $y + 1 = -\\frac{3}{4}x + \\frac{18}{4}$, so $y = -\\frac{3}{4}x + \\frac{9}{2} - 1 = -\\frac{3}{4}x + \\frac{7}{2}$. The $y$-intercept is $\\frac{7}{2}$. Option A ($-4$) is the $y$-intercept of the original line, not the perpendicular line. Option B ($-\\frac{7}{2}$) results from a sign error in computing the intercept. Option C ($\\frac{3}{4}$) comes from using the reciprocal of the original slope without negating it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RO82AT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 200 voters in a city found that 120 support a new park proposal. Based on this sample, what is the best estimate of the proportion of all voters in the city who support the proposal?', NULL, $lyceon_json$[{"key":"A","text":"0.40"},{"key":"B","text":"0.50"},{"key":"C","text":"0.60"},{"key":"D","text":"0.80"}]$lyceon_json$::jsonb, 'C', NULL, E'The sample proportion is \\(\\dfrac{120}{200} = 0.60\\), which is the best estimate of the population proportion. Option A (0.40) computes the proportion who do NOT support the proposal (80/200). Option B (0.50) assumes an even split without using the data. Option D (0.80) results from an arithmetic error such as dividing 120 by 150 or misreading the sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RWO40R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population. Sample 1 has 100 respondents and finds a mean of 74 with a margin of error of 6. Sample 2 has 400 respondents and finds a mean of 71 with a margin of error of 3. Which of the following statements is best supported?', NULL, $lyceon_json$[{"key":"A","text":"Sample 1 provides a more precise estimate because its sample mean is higher."},{"key":"B","text":"Sample 2 provides a more precise estimate because its margin of error is smaller."},{"key":"C","text":"Both samples are equally precise because they come from the same population."},{"key":"D","text":"Neither sample is reliable because their means differ by 3."}]$lyceon_json$::jsonb, 'B', NULL, E'Precision of an estimate is determined by the margin of error, not the magnitude of the sample statistic. Sample 2 has a margin of error of 3, which is smaller than Sample 1''s margin of error of 6, so Sample 2 provides the more precise estimate. This is consistent with the larger sample size reducing variability. Option A confuses a higher sample mean with greater precision; these are unrelated concepts. Option C ignores that sample size affects precision even when sampling from the same population. Option D incorrectly claims both are unreliable; differing sample means are expected due to sampling variability and do not indicate unreliability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RY9LBB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe requires 3 cups of flour to make 24 cookies. At this rate, how many cups of flour are needed to make 40 cookies?', NULL, $lyceon_json$[{"key":"A","text":"4"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"8"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is \\(\\frac{3}{24} = \\frac{1}{8}\\) cup of flour per cookie. For 40 cookies: \\(40 \\times \\frac{1}{8} = 5\\) cups. A is wrong because it results from an arithmetic slip (dividing 40 by 10 instead of 8). C is wrong because it results from an equation setup error (using 3 × 40 ÷ 20 = 6). D is wrong because it confuses the ratio direction, computing 24 ÷ 3 = 8 instead of 3 ÷ 24.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T5E9BN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'What is the vertex of the function $f(x) = (x - 3)^2 + 5$?', NULL, $lyceon_json$[{"key":"A","text":"$(-3, 5)$"},{"key":"B","text":"$(3, 5)$"},{"key":"C","text":"$(3, -5)$"},{"key":"D","text":"$(5, 3)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function is in vertex form $f(x) = a(x - h)^2 + k$, where the vertex is $(h, k)$. Here $h = 3$ and $k = 5$, so the vertex is $(3, 5)$. The answer is B. Option A ($(-3, 5)$) is a sign error: reading $x - 3$ as meaning $h = -3$ instead of $h = 3$. Option C ($(3, -5)$) reflects a concept gap: negating the vertical shift $k$. Option D ($(5, 3)$) results from misreading the question: swapping the coordinates of the vertex.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TWOVHH', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3x - 7}{4} = 5$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The correct answer is $9$. Multiply both sides by $4$ to get $3x - 7 = 20$. Add $7$ to both sides to get $3x = 27$. Divide both sides by $3$ to get $x = 9$. A common error is forgetting to add $7$ before dividing, which would yield $\\frac{20}{3}$, or dividing $20$ by $3$ without isolating the variable term first.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UD2H1H', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $6$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$12\\pi$"},{"key":"B","text":"$36$"},{"key":"C","text":"$36\\pi$"},{"key":"D","text":"$144\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. The area of a circle is $A = \\pi r^2$. With $r = 6$: $A = \\pi(6)^2 = 36\\pi$. Option A ($12\\pi$) is the circumference ($2\\pi r = 2\\pi(6) = 12\\pi$), not the area — a concept gap between the two circle formulas. Option B ($36$) correctly computes $6^2 = 36$ but omits the factor of $\\pi$. Option D ($144\\pi$) uses the diameter ($12$) instead of the radius: $\\pi(12)^2 = 144\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTDCPL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'$$\\begin{cases} 2x - 3y = -16 \\\\ 5x + 2y = -2 \\end{cases}$$ What is the value of $7x - y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-18', ARRAY['-18'], E'The correct answer is $-18$. To eliminate $y$, multiply the first equation by $2$ and the second by $3$: $4x - 6y = -32$ and $15x + 6y = -6$. Adding these gives $19x = -38$, so $x = -2$. Substituting into the first equation: $2(-2) - 3y = -16$, which gives $-4 - 3y = -16$, so $-3y = -12$ and $y = 4$. Therefore $7x - y = 7(-2) - 4 = -14 - 4 = -18$. A common error is finding $x$ and $y$ correctly but computing $7x + y = -14 + 4 = -10$ instead, misreading the sign in the expression. Another trap is making a sign error when solving for $y$ and obtaining $y = -4$, which would give $7(-2) - (-4) = -10$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VHE5V5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 6x + 8y - 11 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The correct answer is $6$. Rewrite the equation by completing the square for both $x$ and $y$. Group the $x$ and $y$ terms: $(x^2 - 6x) + (y^2 + 8y) = 11$. Complete the square: $(x^2 - 6x + 9) + (y^2 + 8y + 16) = 11 + 9 + 16$, which gives $(x - 3)^2 + (y + 4)^2 = 36$. This is the standard form $(x - h)^2 + (y - k)^2 = r^2$ with $r^2 = 36$, so $r = 6$. A common error is to forget to add the completing-the-square constants to the right side, yielding $r^2 = 11$ and $r = \\sqrt{11}$. Another error is to report $r^2 = 36$ as the radius instead of taking the square root.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VPV9Q4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line represented by the equation $y = 3x + 7$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$\\frac{1}{3}$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. In the slope-intercept form $y = mx + b$, the coefficient $m$ of $x$ is the slope. Here $m = 3$. Option A ($-3$) results from incorrectly negating the slope. Option B ($\\frac{1}{3}$) comes from confusing the slope with its reciprocal. Option D ($7$) results from confusing the y-intercept with the slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WVU4K4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $6$ and the hypotenuse has length $10$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\sqrt{136}$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. By the Pythagorean theorem, $a^2 + b^2 = c^2$. With $a = 6$ and $c = 10$: $6^2 + b^2 = 10^2$, so $36 + b^2 = 100$, giving $b^2 = 64$ and $b = 8$. Option A ($4$) is an arithmetic slip, such as computing $10 - 6 = 4$ instead of using the Pythagorean theorem. Option C ($\\sqrt{136}$) results from adding the squares instead of subtracting: $6^2 + 10^2 = 136$, treating the hypotenuse as a leg. Option D ($16$) comes from stopping at $b^2 = 64$ and doubling instead of taking the square root: an error of returning $2 \\times 8$ or confusing $b^2$ with $2b$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X060WT', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$\\begin{cases} x + y = 10 \\\\ x - y = 4 \\end{cases}$$ What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The correct answer is $7$. Adding the two equations eliminates $y$: $(x + y) + (x - y) = 10 + 4$, which gives $2x = 14$. Dividing both sides by $2$ yields $x = 7$. This can be verified by substituting back: $7 + y = 10$ gives $y = 3$, and $7 - 3 = 4$ confirms the solution.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XCIH2Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A survey of 400 randomly selected residents found that 52% prefer candidate A, with a margin of error of 4 percentage points. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 52% of all residents prefer candidate A."},{"key":"B","text":"Between 48% and 56% of all residents are likely to prefer candidate A."},{"key":"C","text":"Candidate A will win the election with certainty."},{"key":"D","text":"At least 56% of all residents prefer candidate A."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the confidence interval for the true population proportion is \\(52\\% \\pm 4\\%\\), or from 48% to 56%. Option A incorrectly treats the sample statistic as the exact population parameter. Option C overstates the conclusion; since the interval includes values below 50%, certainty is not warranted. Option D uses only the upper bound and ignores the lower bound of the interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y40PIF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A $20$-foot ladder leans against a vertical wall, making a $60^\\circ$ angle with the ground. A second ladder reaches the same point on the wall but makes a $45^\\circ$ angle with the ground. What is the length, in feet, of the second ladder?', NULL, $lyceon_json$[{"key":"A","text":"$10\\sqrt{2}$"},{"key":"B","text":"$10\\sqrt{3}$"},{"key":"C","text":"$10\\sqrt{6}$"},{"key":"D","text":"$20\\sqrt{2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. First, find the height the first ladder reaches on the wall: $h = 20 \\sin 60^\\circ = 20 \\cdot \\frac{\\sqrt{3}}{2} = 10\\sqrt{3}$ feet. The second ladder reaches the same height at a $45^\\circ$ angle, so $\\sin 45^\\circ = \\frac{10\\sqrt{3}}{L}$, giving $L = \\frac{10\\sqrt{3}}{\\sin 45^\\circ} = \\frac{10\\sqrt{3}}{\\frac{\\sqrt{2}}{2}} = \\frac{20\\sqrt{3}}{\\sqrt{2}} = \\frac{20\\sqrt{3} \\cdot \\sqrt{2}}{2} = 10\\sqrt{6}$. Option A ($10\\sqrt{2}$) results from using $10$ as the height instead of $10\\sqrt{3}$, omitting the first step. Option B ($10\\sqrt{3}$) gives the height on the wall, not the length of the second ladder. Option D ($20\\sqrt{2}$) comes from incorrectly dividing the original ladder length $20$ by $\\sin 45^\\circ$ without first finding the correct wall height.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YMEH0A', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations $y = x^2$ and $y = 2x + k$ have exactly one solution?', NULL, $lyceon_json$[{"key":"A","text":"$k = 1$"},{"key":"B","text":"$k = -1$"},{"key":"C","text":"$k = 0$"},{"key":"D","text":"$k = 4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: $x^2 = 2x + k$, so $x^2 - 2x - k = 0$. For exactly one solution, the discriminant equals zero: $(-2)^2 - 4(1)(-k) = 0$, giving $4 + 4k = 0$, so $k = -1$. The answer is B. Option A ($k = 1$) is an equation setup error: writing the rearranged equation as $x^2 - 2x + k = 0$ (wrong sign on $k$), yielding discriminant $4 - 4k = 0$ and $k = 1$. Option C ($k = 0$) reflects a concept gap: assuming the line must pass through the origin for tangency. Option D ($k = 4$) is an arithmetic slip: using $b^2 = 4$ as the answer instead of solving $4 + 4k = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YVV5DQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cube has a total surface area of $150$ square centimeters. What is the volume, in cubic centimeters, of the cube?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '125', ARRAY['125'], E'The correct answer is $125$. The surface area of a cube with side length $s$ is $SA = 6s^2$. Setting $6s^2 = 150$ gives $s^2 = 25$, so $s = 5$. The volume is $V = s^3 = 5^3 = 125$ cubic centimeters. A common error is to divide the surface area by $4$ instead of $6$ (confusing the number of faces), getting $s^2 = 37.5$. Another error is to find $s = 5$ but then compute $s^2 = 25$ instead of $s^3 = 125$, returning the area of one face rather than the volume.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YXUC3X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values 3, 5, 7, 7, and 8. What is the mean of this data set?', NULL, $lyceon_json$[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"30"}]$lyceon_json$::jsonb, 'A', NULL, E'The mean is \\(\\frac{3 + 5 + 7 + 7 + 8}{5} = \\frac{30}{5} = 6\\). B is wrong because 7 is the median (and the mode), not the mean — this reflects a concept gap between measures of center. C is wrong because 8 is the maximum value, not the mean (misread question). D is wrong because 30 is the sum of the values before dividing by the count (partial reasoning — stopped before completing the calculation).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z6ZOVN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up the wholesale price of an item by 60% to set the retail price. During a sale, the retail price is then reduced by 25%. The sale price is what percent greater than the wholesale price?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'Let the wholesale price be \\(w\\). The retail price is \\(w \\times 1.60 = 1.60w\\). After a 25% reduction, the sale price is \\(1.60w \\times 0.75 = 1.20w\\). Since \\(1.20w\\) is 120% of \\(w\\), the sale price is 20% greater than the wholesale price. A common error is to assume that a 60% markup followed by a 25% discount results in a 35% net change, but percentage changes do not simply add when applied sequentially.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZA1UOC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two lines intersect at a point. One of the angles formed measures $132^\\circ$. What is the measure, in degrees, of the angle that is vertical to it?', NULL, $lyceon_json$[{"key":"A","text":"$48$"},{"key":"B","text":"$66$"},{"key":"C","text":"$132$"},{"key":"D","text":"$228$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is C. Vertical angles are the pair of non-adjacent angles formed when two lines intersect, and vertical angles are always equal in measure. Since one angle measures $132^\\circ$, the angle vertical to it also measures $132^\\circ$. Option A ($48^\\circ$) is the result of subtracting from $180^\\circ$, which gives a supplementary angle, not a vertical angle. Option B ($66^\\circ$) results from halving $132^\\circ$, which has no geometric basis here. Option D ($228^\\circ$) comes from subtracting $132^\\circ$ from $360^\\circ$, confusing the reflex angle with the vertical angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZO1S2H', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'If $3(2x - 4) - 2(x + 5) = 6$, what is the value of $x - 3$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is B. Distribute on the left side: $3(2x - 4) = 6x - 12$ and $-2(x + 5) = -2x - 10$. Combining gives $6x - 12 - 2x - 10 = 6$, which simplifies to $4x - 22 = 6$. Adding $22$ to both sides yields $4x = 28$, so $x = 7$. The question asks for $x - 3 = 7 - 3 = 4$. Option A ($-4$) results from a sign error in the final subtraction. Option C ($7$) comes from finding $x$ but not subtracting $3$ as the question requires. Option D ($10$) results from an error in distributing the $-2$ across the second parenthetical expression.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZSWRYX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = 2 \\cdot 3^x$ models a bacteria population in thousands. What is the value of $g(4) - g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$54$"},{"key":"C","text":"$108$"},{"key":"D","text":"$162$"}]$lyceon_json$::jsonb, 'C', NULL, E'Compute each value: $g(4) = 2 \\cdot 3^4 = 2 \\cdot 81 = 162$ and $g(3) = 2 \\cdot 3^3 = 2 \\cdot 27 = 54$. Therefore $g(4) - g(3) = 162 - 54 = 108$. The answer is C. Option A ($6$) reflects a concept gap: incorrectly applying $3^4 - 3^3 = 3^{4-3} = 3$ and then $2 \\cdot 3 = 6$, misusing exponent rules. Option B ($54$) is partial reasoning: computing $3^4 - 3^3 = 81 - 27 = 54$ but forgetting to multiply by the coefficient $2$ (or equivalently, computing only $g(3)$). Option D ($162$) results from misreading the question: computing $g(4)$ alone instead of the difference $g(4) - g(3)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22CU70X', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Psychologist Alina Voskresenskaya studied how bilingual speakers switch between languages during casual conversation. She found that speakers do not switch randomly; instead, they tend to switch at grammatical boundaries, such as between clauses or sentences, where the switch causes minimal disruption to the listener''s comprehension. _______ when speakers did switch mid-clause, they almost always did so at points where the grammars of both languages permitted the same word order, suggesting that an underlying structural compatibility governs even apparently spontaneous switches.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first states that speakers switch at grammatical boundaries to minimize disruption. The sentence after the blank adds a further finding: even mid-clause switches follow structural rules. This is an additive, escalating relationship (not only do switches happen at boundaries, but even the exceptions follow grammar-based patterns), so ''Moreover'' (B) is correct. ''In other words'' (A) signals a restatement, but the second finding introduces new evidence about mid-clause switches rather than rephrasing the first finding. ''On the other hand'' (C) signals contrast, but both findings support the same conclusion that switching is rule-governed rather than random. ''Consequently'' (D) implies the mid-clause finding is caused by the boundary-switching finding, but it is an independent observation from the same study, not a logical consequence of the first result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22KEWQL', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would Tomasello most likely respond to Chomsky''s claim about innate grammar?', E'Text 1: Linguist Noam Chomsky has long argued that the capacity for language is an innate biological endowment unique to humans. According to Chomsky, children acquire language so rapidly and uniformly because they are born with an internal grammar—a universal set of linguistic principles hardwired into the brain that constrains the possible forms any human language can take.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22PJI5U', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the authors of Text 2 most likely characterize the relationship between Dweck''s original findings and the results of large-scale implementation?', E'Text 1: Psychologist Carol Dweck''s research on ''growth mindset''—the belief that intelligence and abilities can be developed through effort and learning—has been widely adopted in educational settings. Dweck''s studies found that students who were praised for effort rather than innate talent showed greater persistence when facing difficult tasks and achieved higher academic outcomes over time. Schools across the country have implemented growth mindset interventions, training teachers to emphasize process and effort in their feedback to students.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23473CF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s special archives ______ an invaluable resource for scholars studying medieval European history. Researchers from around the world regularly visit the archives to examine documents that date back to the twelfth century.', $lyceon_json$[{"key":"A","text":"represent"},{"key":"B","text":"represents"},{"key":"C","text":"are"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is ''collection'' (singular), not ''manuscripts'' (the object of the prepositional phrase ''of rare manuscripts''). A singular subject requires a singular verb. ''Represents'' is the singular form and agrees with ''collection'' (B). Option A (''represent'') is a plural verb form that incorrectly agrees with the nearby plural noun ''manuscripts'' rather than the true singular subject ''collection.'' Option C (''are'') is a plural linking verb that fails to agree with the singular subject ''collection.'' Option D (''have been'') uses a plural auxiliary verb (''have'' instead of ''has'') that fails to agree with the singular subject ''collection.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26BL4RA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Linguist John McWhorter has observed that languages tend to become structurally simpler when they are widely adopted by adult second-language learners. Old English, for example, had an elaborate system of noun declensions and grammatical gender, but after extensive contact with Norse-speaking settlers -- who learned English as adults and did not fully acquire these complex features -- many of these inflectional distinctions were lost. McWhorter notes that Mandarin Chinese, which has been learned by vast numbers of non-native speakers throughout its history, is strikingly low in inflectional morphology compared to closely related languages. He argues that this pattern implies that languages which have remained relatively isolated and learned primarily by children within their native communities should tend to ________', $lyceon_json$[{"key":"A","text":"retain or develop greater structural complexity than languages with large populations of adult learners."},{"key":"B","text":"develop writing systems more slowly than languages with extensive contact with other linguistic groups."},{"key":"C","text":"have smaller vocabularies because their speakers have less need to borrow words from other languages."},{"key":"D","text":"be more resistant to phonological change because children acquire pronunciation more precisely than adults."}]$lyceon_json$::jsonb, 'A', NULL, E'McWhorter''s argument is that adult second-language learners simplify languages by failing to acquire complex inflectional features. The logical corollary is that isolated languages learned primarily by children (who fully acquire complex grammar) should retain or develop greater structural complexity (A). B introduces writing systems, which are unrelated to McWhorter''s argument about morphological complexity. C shifts to vocabulary size and borrowing, which is a separate linguistic phenomenon from inflectional morphology. D focuses on phonological change and pronunciation, which is outside the scope of the passage''s argument about grammatical inflection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW272QYFJ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The restoration team faced an unexpected challenge during the final phase of the cathedral ______ the original stained glass windows, which had survived two world wars and a major earthquake, had developed microscopic fractures that were invisible to the naked eye but threatened to shatter under the stress of the new structural reinforcements.', $lyceon_json$[{"key":"A","text":"renovation, the"},{"key":"B","text":"renovation the"},{"key":"C","text":"renovation: the"},{"key":"D","text":"renovation, however, the"}]$lyceon_json$::jsonb, 'C', NULL, E'The first independent clause (''The restoration team faced an unexpected challenge during the final phase of the cathedral renovation'') introduces a general situation, and the second independent clause specifies what that challenge was. A colon is the correct punctuation when the second independent clause directly explains, specifies, or elaborates on the first (C). Option A creates a comma splice by joining two independent clauses with only a comma. Option B creates a run-on (fused) sentence with no punctuation between the two independent clauses. Option D creates a comma splice because ''however'' is a conjunctive adverb, not a coordinating conjunction — commas alone cannot join two independent clauses around it. Additionally, ''however'' implies contrast, which is logically inappropriate here since the second clause explains the first rather than contrasting with it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28OQ452', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to an article about the baobab tree for readers unfamiliar with the species. The student wants to emphasize the tree''s distinctive physical appearance. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A5NF67', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "currency" most nearly means', E'In a 2019 lecture, the historian argued that the political theories of Hannah Arendt still had remarkable currency among scholars of democratic governance. Despite having been formulated in the mid-twentieth century, her concepts of political action and public space continued to shape contemporary debates about civic participation and the nature of authority in ways that few of her peers'' ideas could match.', $lyceon_json$[{"key":"A","text":"denomination"},{"key":"B","text":"wealth"},{"key":"C","text":"relevance"},{"key":"D","text":"novelty"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage states that Arendt''s theories ''still had remarkable currency among scholars'' and ''continued to shape contemporary debates,'' establishing that her ideas remain influential and applicable today. ''Currency'' here means ongoing relevance or acceptance. (C) ''relevance'' preserves this meaning: ''remarkable relevance among scholars'' correctly conveys that the theories remain pertinent. (A) ''denomination'' refers to a unit of monetary value, producing nonsensical ''remarkable denomination among scholars.'' (B) ''wealth'' refers to an abundance of possessions, producing incoherent ''remarkable wealth among scholars'' when applied to theories. (D) ''novelty'' means newness, which directly contradicts the passage''s point that these theories were ''formulated in the mid-twentieth century'' yet remain influential despite their age.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ASNJB3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'When the city of Pompeii was rediscovered in the eighteenth century, scholars initially treated its ruins as a treasure trove of art and artifacts to be extracted and displayed in European collections. It was not until the systematic excavations of Giuseppe Fiorelli in the 1860s that researchers began to understand Pompeii as something far more valuable: a complete snapshot of daily life in the ancient world. Fiorelli''s innovation of excavating entire city blocks rather than individual buildings revealed how Romans of all social classes lived, worked, and interacted. His plaster casts of the victims, created by filling the voids left by decomposed bodies in the volcanic ash, transformed Pompeii from a site of scholarly curiosity into a place of profound human connection.', $lyceon_json$[{"key":"A","text":"It presents a chronological account of how the approach to studying Pompeii shifted from artifact extraction to comprehensive archaeological investigation"},{"key":"B","text":"It argues that Giuseppe Fiorelli was a more talented archaeologist than his predecessors"},{"key":"C","text":"It criticizes eighteenth-century scholars for their careless treatment of Pompeii's ruins"},{"key":"D","text":"It provides a detailed technical explanation of the methods used to create plaster casts of volcanic victims"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves chronologically from eighteenth-century artifact extraction to Fiorelli''s 1860s innovations, tracing how the approach to Pompeii evolved from collecting objects to understanding an entire society. (A) accurately captures this chronological shift in methodology. (B) is wrong because the passage describes a change in approach, not a comparison of personal talent; Fiorelli''s predecessors are not characterized as less skilled, merely as operating under a different framework. (C) is wrong because the passage describes what eighteenth-century scholars did without condemning them; words like ''treasure trove'' are descriptive, not critical. (D) is wrong because the plaster casts are mentioned briefly in the final sentence as one example of Fiorelli''s impact, not as the passage''s central subject or a detailed technical account.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BVE5H0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the provincial government announced plans to convert the abandoned railway corridor into a cycling ______ residents of the adjacent neighborhoods, who had long complained about the deteriorating infrastructure, expressed overwhelming support for the project at a series of public hearings.', $lyceon_json$[{"key":"A","text":"trail. Residents"},{"key":"B","text":"trail residents"},{"key":"C","text":"trail; residents"},{"key":"D","text":"trail, residents"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence begins with a dependent adverbial clause (''When the provincial government announced plans to convert the abandoned railway corridor into a cycling trail''), which must be followed by a comma before the main clause (''residents of the adjacent neighborhoods...expressed overwhelming support''). A comma correctly marks the boundary between the introductory dependent clause and the main clause (D). Option A incorrectly places a period after the dependent clause, creating a fragment (''When the provincial government announced plans...into a cycling trail.'') because the ''When'' clause cannot stand alone as a sentence. Option B omits the comma required after an introductory dependent clause, violating Standard English punctuation conventions. Option C incorrectly uses a semicolon, which requires an independent clause on each side; the ''When'' clause is a dependent clause and cannot precede a semicolon.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CI92IP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if true, would most directly weaken the conclusion described in the text?', E'A team of economists analyzed employment data from 15 countries that had implemented a four-day workweek pilot program between 2018 and 2023. The researchers concluded that reducing the workweek from five days to four, without reducing pay, led to no measurable decline in productivity across the participating firms. They attributed this result to increased employee focus during working hours and reduced absenteeism, arguing that the compressed schedule eliminated low-productivity time that typically occurs during a conventional five-day week.', $lyceon_json$[{"key":"A","text":"Firms that participated in the pilot programs were disproportionately drawn from knowledge-based industries where output is difficult to measure precisely."},{"key":"B","text":"Employee satisfaction surveys showed that workers in the pilot programs reported higher job satisfaction than workers on a five-day schedule."},{"key":"C","text":"Several countries that did not participate in the pilot programs experienced economic downturns during the same period."},{"key":"D","text":"The pilot programs lasted an average of six months, which some researchers consider too short for employees to exhaust any novelty-driven motivation."}]$lyceon_json$::jsonb, 'A', NULL, E'The conclusion is that a four-day workweek causes no measurable productivity decline. A weakens this by suggesting the firms studied were in industries where productivity is hard to measure precisely, undermining the reliability of the ''no measurable decline'' finding -- it may reflect measurement limitations rather than maintained productivity. B strengthens rather than weakens the conclusion by showing a positive outcome. C is about non-participating countries and does not address the productivity claim. D is a reasonable weakener, but it challenges the durability of the finding rather than the finding itself; A more directly undermines the core measurement on which the conclusion rests, making A the strongest choice.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CP9ONH', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "elastic" most nearly means', E'The conductor was known for her elastic interpretation of classical scores. Where other conductors adhered rigidly to established tempos and dynamics, she allowed the music to breathe, adjusting phrasing and rhythm to suit the acoustics of each venue and the particular strengths of the musicians before her. Critics who valued strict fidelity to the composer''s markings often found her performances unsettling, but audiences responded with enthusiasm to the spontaneity and emotional depth of her readings.', $lyceon_json$[{"key":"A","text":"rigid"},{"key":"B","text":"resilient"},{"key":"C","text":"theatrical"},{"key":"D","text":"flexible"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage contrasts the conductor''s approach with those who ''adhered rigidly,'' describing how she adjusted phrasing and rhythm to suit each situation. ''Elastic'' here means adaptable or flexible. (D) ''flexible'' preserves this meaning exactly: a ''flexible interpretation'' is one that adapts to circumstances, matching the described adjustments. (A) ''rigid'' means stiff and unyielding, which is the direct opposite of the conductor''s approach and contradicts the passage''s explicit contrast. (B) ''resilient'' means able to recover from difficulty, but the passage describes adaptability in interpretation, not recovery from hardship; ''resilient interpretation'' changes the meaning entirely. (C) ''theatrical'' means dramatic or exaggerated for effect, which describes a performance style unrelated to the adaptability the passage emphasizes; nothing in the passage suggests showiness.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DEVTGY', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary about urban heat islands for an environmental science journal. The student wants to argue that a specific mitigation strategy is supported by empirical evidence. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ECLVAS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the last sentence in relation to the rest of the passage?', E'The claim that the human trafficking trade rivals oil and arms dealing in global revenue has appeared in policy briefs, news articles, and fundraising appeals since the early 2000s. Its source is typically traced to a 2005 International Labour Organization report, yet the original document made no such comparison. The figure most often cited—$150 billion annually—was published in a 2014 ILO estimate of forced labor profits, not trafficking revenue, and the report''s authors explicitly cautioned against equating the two concepts. Nonetheless, the comparison has proven remarkably durable, appearing even in official government statements, because it serves a rhetorical purpose that resists correction: it conveys urgency and moral gravity in a single, memorable claim.', $lyceon_json$[{"key":"A","text":"It introduces a new argument that contradicts the evidence presented earlier in the passage"},{"key":"B","text":"It explains why the inaccurate comparison described in the passage continues to circulate despite being unfounded"},{"key":"C","text":"It dismisses the significance of the statistical errors documented in the passage"},{"key":"D","text":"It proposes a method for correcting the misattribution discussed in the passage"}]$lyceon_json$::jsonb, 'B', NULL, E'The body of the passage establishes that a widely repeated claim is inaccurately sourced and misrepresents the original data. The final sentence then explains WHY the claim persists despite being wrong: it fulfills a rhetorical need for urgency. (B) accurately captures this explanatory function. (A) is wrong because the last sentence does not contradict the earlier evidence; it builds on it by offering a reason for the claim''s persistence. (C) is wrong because the sentence does not minimize or dismiss the errors; it accounts for why they continue uncorrected. (D) is wrong because the sentence offers no correction method; it explains what makes the claim resistant to correction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FE5AI4', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an essay about the composer Clara Schumann and wants to present a contrast between her public reputation during her lifetime and the way scholars view her today. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G5CUSG', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "sound" most nearly means', E'The architect''s plans for the new community center were praised for being remarkably sound. Every structural element had been carefully calculated, the materials were well-suited to the local climate, and the layout maximized both natural light and energy efficiency. The city council approved the project unanimously, noting that the proposal demonstrated an unusually thorough understanding of the site''s constraints.', $lyceon_json$[{"key":"A","text":"audible"},{"key":"B","text":"well-founded"},{"key":"C","text":"loud"},{"key":"D","text":"intact"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes architectural plans that have been carefully calculated with well-suited materials and efficient layout, then unanimously approved. ''Sound'' here means solid, reliable, and well-founded. (B) ''well-founded'' preserves this meaning exactly: ''remarkably well-founded'' plans are plans with a strong basis. (A) ''audible'' and (C) ''loud'' both relate to the acoustic meaning of ''sound,'' producing nonsensical readings (''plans were remarkably audible/loud''). (D) ''intact'' means undamaged or whole, implying the plans survived something, which contradicts the context of praising the quality of their design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G5XSNW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Appalachian Trail stretches over two thousand miles from Georgia to Maine. Each year, thousands of hikers attempt to complete the entire ______ only about one in four succeeds in finishing the grueling six-month journey.', $lyceon_json$[{"key":"A","text":"trail, only"},{"key":"B","text":"trail only"},{"key":"C","text":"trail. Only"},{"key":"D","text":"trail, however, only"}]$lyceon_json$::jsonb, 'C', NULL, E'The text contains two independent clauses: (1) ''Each year, thousands of hikers attempt to complete the entire trail'' and (2) ''only about one in four succeeds in finishing the grueling six-month journey.'' A period correctly separates these two independent clauses (C). Option A creates a comma splice by joining two independent clauses with only a comma. Option B creates a run-on (fused) sentence by omitting all punctuation between the two independent clauses. Option D creates a comma splice because ''however'' is a conjunctive adverb, not a coordinating conjunction, so commas alone cannot join the two independent clauses around it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HCNBU5', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Linguist Dr. Sarah Park has documented over fifty endangered languages in Southeast ______ focusing particularly on tonal languages spoken by fewer than a thousand people in remote mountain communities of Laos and Vietnam.', $lyceon_json$[{"key":"A","text":"Asia. Focusing"},{"key":"B","text":"Asia; focusing"},{"key":"C","text":"Asia, focusing"},{"key":"D","text":"Asia, she focuses"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase ''focusing particularly on tonal languages spoken by fewer than a thousand people in remote mountain communities of Laos and Vietnam'' is a nonrestrictive participial phrase modifying ''Dr. Sarah Park.'' A comma correctly sets off this modifying phrase from the main clause (C). Option A incorrectly places a period before the participial phrase, creating a sentence fragment (''Focusing particularly on tonal languages...'') because a participial phrase cannot stand alone as a sentence. Option B incorrectly uses a semicolon, which requires an independent clause on each side; a participial phrase is not an independent clause. Option D replaces the participial phrase with an independent clause (''she focuses''), creating a comma splice — two independent clauses joined by only a comma.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IBR43B', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason the researchers found the results of the study surprising?', E'A 2019 study examined the relationship between urban green spaces and cognitive performance in children. Researchers tracked 2,500 children in Barcelona over a 12-month period, measuring their exposure to parks, gardens, and tree-lined streets. The results showed that children with greater access to green spaces scored higher on tests of working memory and attentiveness. What surprised the researchers, however, was that the size of the green space mattered far less than its proximity: children who lived within 300 meters of even a small park showed greater cognitive gains than those who lived near a large park but had to travel more than a kilometer to reach it.', $lyceon_json$[{"key":"A","text":"The cognitive benefits of green spaces were limited to improvements in working memory rather than attentiveness."},{"key":"B","text":"Children in urban areas showed lower cognitive performance than children in rural areas."},{"key":"C","text":"The nearness of green spaces to children's homes was more important than the size of those spaces."},{"key":"D","text":"Only children who visited green spaces daily experienced measurable cognitive improvements."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage explicitly states that what surprised the researchers was that ''the size of the green space mattered far less than its proximity,'' making C the correct answer. A is wrong because the passage states children scored higher on both working memory and attentiveness, not just one. B is wrong because the study compared children within an urban area, never mentioning rural children. D is wrong because daily visits are never mentioned; the study measured proximity, not visit frequency.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IDDV90', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists have long understood that coral reefs support extraordinary biodiversity. Reefs provide shelter and breeding grounds for thousands of fish species, and they protect coastlines from storm damage. _______ coral reefs also play a significant role in local economies, attracting millions of tourists each year who spend money on diving excursions, boat rentals, and coastal hotels.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"However,"},{"key":"C","text":"For instance,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage lists benefits of coral reefs: biodiversity support, coastline protection, and then adds another benefit (economic value through tourism). This is an additive relationship, so ''In addition'' (A) is correct. ''However'' (B) signals contrast, but the sentence continues listing benefits rather than introducing a counterpoint. ''For instance'' (C) signals an example, but the economic role is a separate benefit, not an example of storm protection. ''As a result'' (D) implies the economic benefit is caused by the previously mentioned ecological benefits, but tourism is an independent benefit, not a consequence of reef biodiversity or coastline protection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JRVMI6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "economy" most nearly means', E'The poet''s late work was celebrated for its remarkable economy. In her final collection, she distilled complex emotional landscapes into poems of rarely more than ten lines, each word carrying the weight of a sentence, each image serving multiple thematic purposes simultaneously. Reviewers noted that where her earlier volumes had sprawled across pages of dense stanzas, these spare compositions achieved greater emotional impact through radical compression.', $lyceon_json$[{"key":"A","text":"commerce"},{"key":"B","text":"efficiency"},{"key":"C","text":"prosperity"},{"key":"D","text":"scarcity"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes poems that achieve maximum emotional impact through minimal means: distilling complexity into few lines, each word carrying great weight. ''Economy'' here means efficiency of expression—achieving much with little. (B) ''efficiency'' preserves this meaning: ''remarkable efficiency'' in writing means accomplishing a great deal with minimal material. (A) ''commerce'' means the activity of buying and selling goods, producing nonsensical ''celebrated for its remarkable commerce'' when describing poetic technique. (C) ''prosperity'' means financial wealth or success, producing nonsensical ''celebrated for its remarkable prosperity'' when describing poetic craft. (D) ''scarcity'' means rarity or insufficiency, implying there is too little of the work; the passage describes the quality within each poem, not the quantity of output.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JZKQNC', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the early twentieth century, many American architects embraced the Beaux-Arts style, designing grand public buildings adorned with classical columns and ornate facades. The style dominated civic architecture for decades. _______ by the 1930s, a younger generation of architects began championing modernism, arguing that buildings should prioritize function over decoration and that industrial materials like steel and glass could achieve a beauty of their own.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Therefore,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage establishes that the Beaux-Arts style dominated civic architecture, and the sentence after the blank introduces a shift: younger architects rejected ornament in favor of modernism. This is a concessive contrast (the style dominated, yet a new movement arose), making ''Nevertheless'' (C) correct. ''Similarly'' (A) signals likeness, but modernism opposed Beaux-Arts rather than resembling it. ''Specifically'' (B) would introduce a detail elaborating on the same point, but the sentence introduces a competing movement, not a specific example of Beaux-Arts dominance. ''Therefore'' (D) implies the rise of modernism was a logical consequence of Beaux-Arts dominance, but the passage presents it as a countermovement, not a direct result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L9DI1R', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists have hypothesized that the decline in sea otter populations along the Pacific coast has contributed to the destruction of kelp forests in the region. Sea otters are known to prey on sea urchins, which feed on kelp. Without otters to control their numbers, sea urchin populations can expand rapidly and consume large amounts of kelp, transforming dense underwater forests into barren expanses known as urchin barrens.', $lyceon_json$[{"key":"A","text":"Kelp forests in areas where sea otter populations have remained stable show significantly less urchin damage than kelp forests in areas where otters have disappeared."},{"key":"B","text":"Sea urchins are capable of surviving in a wide range of ocean temperatures and depths."},{"key":"C","text":"Kelp forests provide habitat for hundreds of marine species beyond sea otters and sea urchins."},{"key":"D","text":"Sea otter populations have declined primarily due to oil spills and predation by orcas."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis is that otter population decline caused kelp forest destruction via unchecked sea urchin growth. A directly supports this by showing a correlation: where otters remain, kelp damage is lower. B is irrelevant because urchin temperature tolerance does not address whether otter decline caused kelp loss. C is irrelevant because the ecological importance of kelp forests does not support the causal mechanism described. D explains why otters declined but does not support the link between otter decline and kelp destruction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M7FLJK', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively illustrate the claim made in the text?', E'In her novels, Toni Morrison frequently employed a narrative technique in which the central traumatic event of the story is initially presented only in fragments, with full details emerging gradually as different characters recall and recount their experiences. This approach mirrors the psychological reality of trauma, in which memories are often fragmented and reconstructed over time rather than experienced as a single coherent narrative.', $lyceon_json$[{"key":"A","text":"\"Morrison's prose style is notable for its lyrical quality, drawing on rhythms and cadences rooted in African American oral traditions.\""},{"key":"B","text":"\"In Beloved, the reader pieces together the circumstances of Sethe's act only through scattered recollections from multiple narrators, each revealing a new dimension of the event.\""},{"key":"C","text":"\"Morrison's novels consistently center the experiences of Black communities in the American Midwest, particularly in small-town settings.\""},{"key":"D","text":"\"Morrison received the Nobel Prize in Literature in 1993, becoming the first African American woman to receive the honor.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The passage claims Morrison used fragmented narration of a central traumatic event, with details emerging gradually through different characters'' recollections. B directly illustrates this technique by describing how Beloved reveals Sethe''s act through scattered recollections from multiple narrators. A discusses Morrison''s prose style and oral traditions, which is unrelated to the narrative fragmentation technique. C addresses the geographic and demographic settings of her novels, not narrative technique. D is a biographical fact about an award, not evidence of the described literary technique.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MZV99L', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The research team''s three-year study concluded that the most effective strategies for reducing hospital readmission rates were providing patients with comprehensive discharge instructions, scheduling follow-up appointments before patients leave the hospital, ______ regular communication between primary care physicians and specialists.', $lyceon_json$[{"key":"A","text":"and to ensure"},{"key":"B","text":"and the establishment of"},{"key":"C","text":"and ensuring"},{"key":"D","text":"and they ensured"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence contains a list of three strategies, the first two of which are gerund phrases: ''providing patients with comprehensive discharge instructions'' and ''scheduling follow-up appointments before patients leave the hospital.'' Parallel structure requires the third item to also be a gerund phrase. ''And ensuring regular communication'' maintains the gerund pattern (C). Option A (''and to ensure'') switches to an infinitive phrase, breaking the parallel gerund structure. Option B (''and the establishment of'') switches to a noun phrase, breaking the parallel gerund structure. Option D (''and they ensured'') switches to a finite clause with a subject and conjugated verb, breaking the parallel gerund structure and introducing a pronoun (''they'') with no clear antecedent.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OQRUXW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city''s transportation department recently announced that each of the proposed bus routes would be evaluated for ______ potential to reduce traffic congestion in the downtown core. The evaluation process, which is expected to take six months, will include input from community advisory boards and urban planning consultants.', $lyceon_json$[{"key":"A","text":"their"},{"key":"B","text":"its"},{"key":"C","text":"it's"},{"key":"D","text":"they're"}]$lyceon_json$::jsonb, 'B', NULL, E'The pronoun must agree with its antecedent ''each,'' which is grammatically singular. The correct possessive pronoun is ''its'' (singular possessive) (B). Option A (''their'') is a plural possessive pronoun that does not agree with the singular antecedent ''each'' — though ''routes'' is nearby and plural, the antecedent is ''each,'' which is singular. Option C (''it''s'') is a contraction of ''it is,'' not a possessive pronoun; ''it is potential to reduce traffic congestion'' is ungrammatical. Option D (''they''re'') is a contraction of ''they are,'' which is both plural (disagreeing with ''each'') and not a possessive form; ''they are potential to reduce traffic congestion'' is ungrammatical.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OVXP7N', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'The monarch butterfly''s annual migration spans up to 3,000 miles, from breeding grounds in the northeastern United States and southern Canada to overwintering sites in central Mexico''s oyamel fir forests. Unlike many migratory species, individual monarchs complete only one leg of the journey; it takes three to four generations to complete the full round trip. Scientists have determined that the butterflies navigate using a time-compensated sun compass located in their antennae, which allows them to maintain a consistent southwesterly bearing regardless of weather conditions.', $lyceon_json$[{"key":"A","text":"To advocate for increased funding for monarch butterfly conservation efforts"},{"key":"B","text":"To describe the monarch butterfly's migration and explain the navigational mechanism the species uses"},{"key":"C","text":"To compare the monarch butterfly's migration with those of other migratory species"},{"key":"D","text":"To challenge a widely held misconception about how monarch butterflies navigate"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents factual information about the monarch butterfly''s migration (distance, multi-generational nature) and then explains the navigational mechanism (time-compensated sun compass). (B) accurately captures both elements: description of the migration and explanation of navigation. (A) is wrong because the passage contains no advocacy, funding requests, or conservation appeals. (C) is wrong because although other migratory species are briefly mentioned for contrast, the passage does not compare migrations; the focus remains entirely on monarchs. (D) is wrong because the passage presents scientific findings without identifying or correcting any misconception.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QZ6SGC', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Historian Frederick Jackson Turner''s 1893 ''frontier thesis'' proposed that American democracy and individualism were fundamentally shaped by the experience of westward expansion. Turner argued that the frontier—the meeting point between civilization and wilderness—served as a crucible in which European customs were shed and a distinctly American character was forged through the challenges of settling new territory.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SLGKRJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'During the late nineteenth century, the construction of transcontinental railroads in the United States was frequently celebrated as a triumph of engineering and national unity. However, historian Richard White has argued that these railroads were not, as popular accounts suggest, built in response to overwhelming economic demand. Instead, White contends, they were largely speculative ventures financed through government subsidies and foreign investment, built ahead of the settlement and commerce they were supposed to serve. Many of these railroads went bankrupt within a decade of completion, which White argues demonstrates that ________', $lyceon_json$[{"key":"A","text":"the engineering challenges of building railroads across mountainous terrain were frequently underestimated by investors."},{"key":"B","text":"foreign investors were more willing than domestic investors to accept the financial risks associated with railroad construction."},{"key":"C","text":"the railroads were built to meet an anticipated demand that, in many cases, did not materialize quickly enough to sustain them financially."},{"key":"D","text":"the federal government deliberately encouraged railroad construction to provoke the settlement of western territories."}]$lyceon_json$::jsonb, 'C', NULL, E'White''s argument is that railroads were speculative and built ahead of demand. The bankruptcies logically demonstrate that the anticipated demand did not materialize quickly enough (C). A shifts to engineering challenges, which are not part of White''s argument about economic demand. B focuses on a comparison between foreign and domestic investors that the passage does not develop. D introduces a deliberate government strategy to provoke settlement, which goes beyond what the passage states; the passage mentions government subsidies but does not claim the government''s goal was to provoke settlement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2THXOXT', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'The migration patterns of monarch butterflies have long fascinated researchers. Each autumn, millions of monarchs travel from southern Canada and the northern United States to overwintering sites in central Mexico, covering distances of up to 3,000 miles. Unlike most migratory species, no single monarch completes the entire round trip. Instead, the return journey northward takes multiple generations, with each successive generation continuing the trek. Scientists have determined that monarchs use a combination of the sun''s position and Earth''s magnetic field to navigate with remarkable precision.', $lyceon_json$[{"key":"A","text":"Monarch butterflies rely on Earth's magnetic field more than on the sun to navigate during migration."},{"key":"B","text":"Monarch butterflies undertake a long multigenerational migration using sophisticated navigational methods."},{"key":"C","text":"Scientists have only recently discovered that monarch butterflies migrate to Mexico each autumn."},{"key":"D","text":"The migration of monarch butterflies is endangered due to habitat loss in central Mexico."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes two main points about monarch migration: it spans thousands of miles across multiple generations, and monarchs navigate using the sun and magnetic field. Choice B captures both elements. A is wrong because the passage says monarchs use a combination of both the sun and magnetic field, not that one is more important. C is wrong because the passage never states this is a recent discovery. D is wrong because habitat loss and endangerment are never mentioned in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U19Y5O', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The axolotl, a salamander native to lakes near Mexico City, possesses an extraordinary ability: it can regenerate entire limbs, portions of its spinal cord, and even parts of its brain without scarring. Most vertebrates, including humans, respond to severe injuries by forming scar tissue, which restores structural integrity but not original function. Researchers studying axolotl regeneration have discovered that after an injury, the axolotl''s cells at the wound site revert to a stem-cell-like state, allowing them to redevelop into the specific tissues needed. This finding suggests that the barrier to regeneration in other vertebrates may not be the absence of regenerative genes but rather ________', $lyceon_json$[{"key":"A","text":"the inability of their cells to revert to an undifferentiated state after injury."},{"key":"B","text":"the greater complexity of their nervous systems compared to the axolotl's."},{"key":"C","text":"the fact that most vertebrates live in terrestrial rather than aquatic environments."},{"key":"D","text":"the limited research funding available for vertebrate regeneration studies."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that axolotl cells revert to a stem-cell-like state to regenerate, while other vertebrates instead form scar tissue. The logical completion is that the barrier in other vertebrates is the inability of their cells to perform this same reversion (A). B introduces nervous system complexity, which the passage never discusses. C introduces habitat differences, which are unrelated to the cellular mechanism described. D shifts to research funding, which is entirely outside the scope of the biological argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WQZ03O', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the overall structure of the text?', E'Conventional models of earthquake prediction have relied on identifying seismic precursors, such as foreshocks or changes in groundwater levels, to forecast when a major earthquake might occur. However, a comprehensive analysis of 40 years of global seismic data, published in 2021, found that none of these precursors occurred reliably enough to serve as a basis for prediction. The study concluded that earthquake prediction, as traditionally conceived, may be fundamentally impossible because the processes that determine whether a small rupture will cascade into a large earthquake are inherently chaotic. Rather than pursuing prediction, the researchers argued, resources should be directed toward improving building codes and early warning systems that detect earthquakes seconds after they begin.', $lyceon_json$[{"key":"A","text":"It introduces a new methodology for earthquake prediction that challenges the conventional approach."},{"key":"B","text":"It presents evidence that undermines the foundational assumption described in the first sentence."},{"key":"C","text":"It provides an example of a seismic precursor that has proved unreliable over time."},{"key":"D","text":"It explains why researchers initially believed foreshocks could predict major earthquakes."}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence establishes that conventional models relied on seismic precursors for prediction. The second sentence introduces a study showing that none of these precursors occurred reliably enough, directly undermining that foundational assumption. B correctly captures this structural relationship. A is wrong because the second sentence does not introduce a new methodology; it reports negative findings about existing methods. C is wrong because the second sentence discusses the entire class of precursors failing, not a single example. D is wrong because the second sentence does not explain historical reasoning about foreshocks; it reports that precursors in general were unreliable.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
